(function(){
'use strict';
const C=window.SMRF,$=id=>document.getElementById(id),all=q=>Array.from(document.querySelectorAll(q));
const esc=v=>String(v).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const n=(v,d=1)=>Number(v).toFixed(d),signed=(v,d=1)=>`${v>0?'+':''}${n(v,d)}`;
const STORAGE='smrf.scenarios.v1',DRAFT='smrf.draft.v1';
let settings=C.defaults(),saved=[],selection={type:'catchment',id:'SC-03'},mode='surface',zoom=1,view='explorer',comparison='current',validated=null,toastTimer;
try{const draft=localStorage.getItem(DRAFT);if(draft)settings=C.validate(JSON.parse(draft));}catch{/* A malformed draft never replaces safe defaults. */}
try{const rows=JSON.parse(localStorage.getItem(STORAGE)||'[]');if(Array.isArray(rows))saved=rows.slice(0,20).map(x=>({id:String(x.id).slice(0,80),name:String(x.name).slice(0,60),created:String(x.created).slice(0,50),settings:C.validate(x.settings)}));}catch{saved=[];}
function notify(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,4800);}
function persistDraft(){try{localStorage.setItem(DRAFT,JSON.stringify(settings));}catch{/* Current work remains available for export. */}}
function storeScenarios(){try{localStorage.setItem(STORAGE,JSON.stringify(saved));return true;}catch{return false;}}
function signature(){return JSON.stringify(settings);}
function settingsChanged(){settings=C.validate(settings);validated=null;persistDraft();render();}
const titles={project:['Upload & customize','Upload your model. Customize its refinements.','Start with a baseline INP, then choose impervious-area, street, parking and green-space refinements.'],explorer:['Model explorer','Inspect your model. Refine with evidence.','Explore how better surface and street information changes a model’s next steps.'],workflow:['Refinement workflow','Make every refinement traceable.','See what changes now, what needs regeneration and what must be validated next.'],scenarios:['Scenario lab','Keep the baseline. Compare the refinements.','Preserve each choice and compare its surface inputs before running the next model.'],data:['Data & assumptions','Know what is data. Know what is assumed.','Inspect the demo attributes and the route to your real SWMManywhere project.']};
function showView(next,updateHash=true){if(!titles[next])next='project';view=next;for(const key of Object.keys(titles)){$('view-'+key).hidden=key!==view;$('view-'+key).classList.toggle('active',key===view);}all('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('view-label').textContent=titles[view][0];$('page-title').textContent=titles[view][1];$('page-subtitle').textContent=titles[view][2];$('demo-note').hidden=view==='project';$('demo-metrics').hidden=view==='project';$('save-button').hidden=view==='project';$('customize-button').hidden=view==='project';$('workspace-badge').textContent=view==='project'?'CUSTOM WORKSPACE':'DEMO DATA';$('workspace-badge').classList.toggle('demo',view!=='project');$('workspace-badge').classList.toggle('live',view==='project');$('dataset-eyebrow').textContent=view==='project'?'YOUR DATA · LOCAL PYTHON PROCESSING':'SYNTHETIC DRAINAGE · FICTIONAL DISTRICT';if(updateHash)history.replaceState(null,'','#'+view);}
function renderControls(){
 $('source').value=settings.source;
 for(const k of ['streets','parking','green','terrain','alignment'])$(k).checked=settings[k];
 const polygon=settings.source==='baseline';for(const k of ['streets','parking','green'])$(k).disabled=!polygon;
 $('width').value=settings.width;$('width').disabled=!polygon||!settings.streets;$('width-field').classList.toggle('disabled',$('width').disabled);$('width-value').textContent=n(settings.width)+' m';
 $('source-help').textContent=polygon?'Demo baseline: roofs, 6 m streets and a known green-area classification error.':settings.source==='raster'?'Complete demo coverage replaces each fraction. Add-on surface toggles are disabled to avoid double counting.':'Each entered fraction replaces its catchment total. Select a subcatchment in the inspector to edit it.';
 $('pending-note').hidden=!(settings.terrain||settings.alignment);
}
function renderMetrics(){const t=C.totals(settings),s=C.stages(settings);$('metric-pct').textContent=n(t.pct);$('metric-area').textContent=n(t.imp,2);$('metric-delta').textContent=Math.abs(t.deltaPct)<.001?'Baseline':signed(t.deltaPct)+' pp';$('metric-delta').classList.toggle('changed',Math.abs(t.deltaPct)>=.001);$('metric-stages').textContent=s.filter(x=>x.active).length;$('nav-count').textContent=s.filter(x=>x.active).length;$('geometry-tag').textContent=settings.terrain||settings.alignment?'Regeneration requested':'Geometry retained';}
function fillFor(c){const a=C.accounting(c,settings),d=a.pct-100*C.baseline(c)/c.area;if(mode==='network')return '#e2e9d7';if(mode==='change')return Math.abs(d)<.05?'#e4e8dc':d>0?(d>8?'#c9ab71':'#e1cf9e'):(d<-5?'#99bba8':'#c2d9c7');return a.pct<35?'#e4edd6':a.pct<45?'#d6e3bd':a.pct<55?'#bfd29c':a.pct<65?'#a7bf82':'#8daa6d';}
function mapPosition(c){return {'SC-01':{x:130,y:230},'SC-02':{x:450,y:125},'SC-03':{x:660,y:255},'SC-04':{x:145,y:410},'SC-05':{x:485,y:434},'SC-06':{x:655,y:390}}[c.id];}
function renderMap(){
 $('catchment-layer').innerHTML=C.catchments.map(c=>{const a=C.accounting(c,settings),delta=a.pct-100*C.baseline(c)/c.area;return `<polygon class="catchment ${selection.type==='catchment'&&selection.id===c.id?'selected':''}" points="${c.points}" fill="${fillFor(c)}" data-object="catchment:${c.id}" tabindex="0" role="button" aria-label="${c.id}, ${esc(c.name)}, ${n(a.pct)} percent impervious${mode==='change'?', change '+signed(delta)+' percentage points':''}"><title>${c.id} · ${esc(c.name)} · ${n(a.pct)}% impervious</title></polygon>`;}).join('');
 $('pipe-layer').innerHTML=C.pipes.map(p=>{const a=C.nodes.find(x=>x.id===p.from),b=C.nodes.find(x=>x.id===p.to),dx=b.x-a.x,dy=b.y-a.y;const len=Math.sqrt(dx*dx+dy*dy);return `<g class="map-object" data-object="pipe:${p.id}" tabindex="0" role="button" aria-label="${p.id}, ${p.diameter} millimetre pipe, ${p.from} to ${p.to}"><title>${p.id} · ${p.diameter} mm · ${p.length} m</title><path class="pipe-hit" d="M${a.x} ${a.y}L${b.x} ${b.y}"/><path class="pipe-visible ${selection.type==='pipe'&&selection.id===p.id?'selected':''}" d="M${a.x} ${a.y}L${b.x} ${b.y}"/><path d="M${a.x+dx*.43} ${a.y+dy*.43}l${dx/len*10} ${dy/len*10}" stroke="#246e5b" stroke-width="1.8" fill="none" marker-end="url(#flow-arrow)" pointer-events="none"/></g>`;}).join('');
 $('node-layer').innerHTML=C.nodes.map(node=>`<g class="map-object" data-object="node:${node.id}" tabindex="0" role="button" aria-label="${node.id}, ${node.type==='outfall'?'demo outfall':'demo junction'}"><title>${node.id} · invert ${n(node.invert)} m</title>${node.type==='outfall'?`<rect x="${node.x-6}" y="${node.y-6}" width="12" height="12" rx="2" class="node-circle ${selection.type==='node'&&selection.id===node.id?'selected':''}"/>`:`<circle cx="${node.x}" cy="${node.y}" r="5" class="node-circle ${selection.type==='node'&&selection.id===node.id?'selected':''}"/>`}</g>`).join('');
 $('label-layer').innerHTML=C.catchments.map(c=>{const p=mapPosition(c),a=C.accounting(c,settings);return `<text x="${p.x}" y="${p.y-16}" text-anchor="middle" class="catchment-label">${c.id}</text><text x="${p.x}" y="${p.y}" text-anchor="middle" class="catchment-sub">${mode==='change'?signed(a.pct-100*C.baseline(c)/c.area)+' pp':n(a.pct)+'% impervious'}</text>`;}).join('')+C.nodes.map(p=>`<text class="node-label" x="${p.x+10}" y="${p.y-9}">${p.id}</text>`).join('');
 $('label-layer').style.display=$('show-labels').checked?'':'none';$('building-layer').style.display=$('show-buildings').checked?'':'none';
 const includeParking=settings.source==='raster'||(settings.source==='baseline'&&settings.parking);$('parking-layer').style.opacity=includeParking?'0.8':'0.2';
 const greenVerified=settings.source==='raster'||(settings.source==='baseline'&&settings.green);$('green-layer').setAttribute('stroke',greenVerified?'#5c8c5a':'#9cb693');$('green-layer').setAttribute('stroke-width',greenVerified?'2':'1');
 const roadWidth=settings.source==='baseline'&&settings.streets?14*settings.width/6:14;const roads=all('#street-layer path');if(roads[0])roads[0].setAttribute('stroke-width',roadWidth+6);if(roads[1])roads[1].setAttribute('stroke-width',roadWidth);
 const swatch=(color,label)=>`<span><i class="legend-swatch" style="background:${color}"></i>${label}</span>`;
 $('map-legend').innerHTML=mode==='change'?swatch('#99bba8','Less impervious')+swatch('#e4e8dc','Unchanged')+swatch('#c9ab71','More impervious'):`${swatch('#e4edd6','< 35%')}${swatch('#d6e3bd','35–45%')}${swatch('#bfd29c','45–55%')}${swatch('#a7bf82','55–65%')}${swatch('#8daa6d','≥ 65%')}`;
 if(mode==='network')$('map-legend').innerHTML='<span><i class="legend-line"></i>Directed demo pipe</span><span>○ Junction</span><span>□ Outfall</span>';
 else $('map-legend').innerHTML+='<span><i class="legend-line"></i>Pipe</span>';
 all('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode));});
 updateZoom();
}
function createBuildings(){let svg='';const rows=[{y:135,start:98,count:22},{y:250,start:112,count:21},{y:342,start:103,count:22},{y:453,start:215,count:17}];for(const r of rows){for(let i=0;i<r.count;i++){const x=r.start+i*26;if([170,190,380,400,590,610].some(z=>Math.abs(x-z)<18))continue;const w=12+(i%3)*2,h=13+(i%4)*3;svg+=`<rect x="${x}" y="${r.y+(i%3)*5}" width="${w}" height="${h}" rx="1.5" fill="#f9f9ee" stroke="#a9b796" stroke-width=".8" transform="rotate(${i%2===0?-4:4} ${x} ${r.y})"/>`;}}$('building-layer').innerHTML=svg;}
function kv(label,value){return `<div class="kv"><span>${label}</span><strong>${esc(value)}</strong></div>`;}
function bar(label,value,area,cls=''){return `<div class="bar-row"><span>${label}</span><span>${n(value,2)} ha</span></div><div class="bar-track ${cls}"><span style="width:${Math.max(0,Math.min(100,value/area*100))}%"></span></div>`;}
function renderInspector(){
 $('object-select').value=selection.type+':'+selection.id;
 let h='';
 if(selection.type==='catchment'){
  const c=C.catchments.find(x=>x.id===selection.id),a=C.accounting(c,settings),base=100*C.baseline(c)/c.area;
  h=`<div class="object-heading"><span class="object-tag">SUBCATCHMENT</span><h3>${c.id}</h3><p>${esc(c.name)}</p></div>${kv('Gross area',n(c.area,2)+' ha')}${kv('Outlet node',c.outlet)}${kv('Demo surface slope',n(c.slope)+'%')}${kv('Baseline imperviousness',n(base)+'%')}<div class="inspector-stat"><span class="field-label">CURRENT IMPERVIOUSNESS</span><div class="stat-value">${n(a.pct)}<small>%</small></div><span class="small">${signed(a.pct-base)} pp from baseline</span></div>`;
  if(settings.source==='manual')h+=`<div class="manual-field"><label class="field-label" for="manual-pct">Set impervious fraction (%)</label><input id="manual-pct" type="number" min="0" max="100" step="0.1" value="${n(settings.manual[c.id])}" aria-describedby="manual-error"><p id="manual-error" class="error" hidden></p></div>`;
  if(settings.source==='baseline')h+=`<div class="breakdown"><h4>Surface accounting</h4>${bar('Roofs',a.roof,c.area)}${bar('Streets',a.road,c.area,'roads')}${bar('Added parking',a.parking,c.area,'parking')}${bar('Baseline false green',c.green,c.area)}${bar('Removed false green',a.correction,c.area,'correction')}<div class="kv"><span>Proposed impervious area</span><strong>${n(a.area,2)} ha</strong></div></div>`;
  else h+=`<div class="breakdown"><h4>${a.method}</h4>${kv('Proposed impervious area',n(a.area,2)+' ha')}${kv('Pervious remainder',n(c.area-a.area,2)+' ha')}</div>`;
  h+=`<div class="inspector-notice"><strong>${settings.terrain?'Boundary regeneration requested.':'Baseline boundary retained.'}</strong><br>${settings.terrain?'These fractions still use the demo boundaries. Recalculate them after actual redelineation.':'Surface changes update this object’s proposed fraction without moving its boundary.'}</div>`;
 }else if(selection.type==='pipe'){
  const p=C.pipes.find(x=>x.id===selection.id),a=C.nodes.find(x=>x.id===p.from),b=C.nodes.find(x=>x.id===p.to),slope=(a.invert-b.invert)/p.length*100;
  h=`<div class="object-heading"><span class="object-tag">SYNTHETIC CONDUIT</span><h3>${p.id}</h3><p>${p.from} → ${p.to}</p></div>${kv('Demo length',p.length+' m')}${kv('Circular diameter',p.diameter+' mm')}${kv('Upstream invert',n(a.invert)+' m')}${kv('Downstream invert',n(b.invert)+' m')}${kv('Derived invert slope',n(slope,2)+'%')}<div class="inspector-stat"><span class="field-label">HYDRAULIC PERFORMANCE</span><div class="stat-value" style="font-size:19px">Not simulated</div><span class="small">No flow, capacity or surcharge prediction</span></div><div class="inspector-notice">Surface refinements do not resize this pipe. A connected runner must regenerate or edit the .inp and execute SWMM before performance can be assessed.</div>`;
 }else{
  const node=C.nodes.find(x=>x.id===selection.id),up=C.pipes.filter(p=>p.to===node.id),down=C.pipes.find(p=>p.from===node.id),linked=C.catchments.filter(c=>c.outlet===node.id);
  h=`<div class="object-heading"><span class="object-tag">${node.type==='outfall'?'DEMO OUTFALL':'DEMO JUNCTION'}</span><h3>${node.id}</h3><p>Fixed demo network geometry</p></div>${kv('Invert elevation',n(node.invert)+' m')}${kv('Rim elevation',node.rim===null?'Not specified':n(node.rim)+' m')}${kv('Incoming pipes',up.map(p=>p.id).join(', ')||'None')}${kv('Outgoing pipe',down?down.id:'Outfall')}${kv('Linked subcatchments',linked.map(c=>c.id).join(', ')||'None')}<div class="inspector-stat"><span class="field-label">DEMO CONNECTIVITY</span><div class="stat-value" style="font-size:21px">${node.type==='outfall'?'Terminal outlet':'Path to OF1'}</div><span class="small">Graph path checked; hydraulics pending</span></div><div class="inspector-notice">Elevations use an arbitrary local demo datum. They are not surveyed levels or a recommended design.</div>`;
 }
 $('inspector').innerHTML=h;
}
function renderWorkflow(){
 $('workflow-list').innerHTML=C.stages(settings).map((s,i)=>`<article class="workflow-stage ${s.active?'affected':''}"><span class="stage-index">${String(i+1).padStart(2,'0')}</span><div class="stage-top"><h3>${s.title}</h3><span class="badge ${!s.active?'inactive':s.id==='surface'?'live':'pending'}">${!s.active?'RETAIN BASELINE':s.id==='surface'?'AREA PREVIEW LIVE':'EXTERNAL WORK REQUESTED'}</span></div><p>${esc(s.text)}</p><div class="stage-owner">${esc(s.owner)}</div></article>`).join('');
 if(validated!==signature())$('validation-receipt').innerHTML='<div class="panel-title"><h2>Demo validation</h2></div><div class="panel-body"><p class="muted">Validate the current plan to check surface balance and the fixed demo graph.</p></div>';
}
function renderScenarios(){
 const t=C.totals(settings),base=C.totals(C.defaults());
 let h=`<article class="scenario-card baseline"><div class="sc-meta"><span>M0 · IMMUTABLE BASELINE</span><span>DEMO</span></div><h3>Buildings + 6 m streets</h3><div class="scenario-number">${n(base.pct)}<small>% impervious</small></div><p>${n(base.imp,2)} ha · fixed geometry<br>Parking omitted; green false positives retained.</p><div class="sc-actions"><button data-scenario-action="baseline">Load baseline choices</button></div></article>`;
 h+=`<article class="scenario-card draft"><div class="sc-meta"><span>CURRENT DRAFT</span><span>LIVE</span></div><h3>${settings.source==='raster'?'Complete land-cover map':settings.source==='manual'?'Manual surface fractions':'Buildings + streets with refinements'}</h3><div class="scenario-number">${n(t.pct)}<small>% impervious</small></div><p>${n(t.imp,2)} ha · ${signed(t.deltaPct)} pp vs baseline<br>${settings.terrain||settings.alignment?'Geometry regeneration requested.':'Baseline geometry retained.'}</p><div class="sc-actions"><button data-scenario-action="save">Save this scenario</button><button data-scenario-action="export-current">Export plan</button></div></article>`;
 h+=saved.map(s=>{const t=C.totals(s.settings);return `<article class="scenario-card"><div class="sc-meta"><span>SAVED LOCALLY</span><span>DEMO</span></div><h3>${esc(s.name)}</h3><div class="scenario-number">${n(t.pct)}<small>% impervious</small></div><p>${n(t.imp,2)} ha · ${signed(t.deltaPct)} pp vs baseline<br>${s.settings.terrain||s.settings.alignment?'Regeneration requested.':'Baseline geometry retained.'}</p><div class="sc-actions"><button data-scenario-action="load" data-id="${esc(s.id)}">Load</button><button data-scenario-action="compare" data-id="${esc(s.id)}">Compare</button><button data-scenario-action="export" data-id="${esc(s.id)}">Export</button><button data-scenario-action="delete" data-id="${esc(s.id)}" aria-label="Delete saved scenario ${esc(s.name)}">Delete</button></div></article>`;}).join('');
 $('scenario-cards').innerHTML=h;
 $('compare-select').innerHTML='<option value="current">Current draft</option>'+saved.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');if(!saved.some(s=>s.id===comparison))comparison='current';$('compare-select').value=comparison;renderComparison();
}
function renderComparison(){const s=comparison==='current'?settings:(saved.find(x=>x.id===comparison)||{}).settings||settings;const t=C.totals(s);$('comparison-rows').innerHTML=C.catchments.map(c=>{const base=100*C.baseline(c)/c.area,a=C.accounting(c,s);return `<tr><td><strong>${c.id}</strong><span class="subtext">${c.name}</span></td><td>${n(c.area,2)}</td><td>${n(base)}</td><td>${n(a.pct)}</td><td>${signed(a.pct-base)}</td></tr>`;}).join('');$('comparison-total').innerHTML=`<tr><td>Area-weighted total</td><td>${n(t.area,2)}</td><td>${n(t.basePct)}</td><td>${n(t.pct)}</td><td>${signed(t.deltaPct)}</td></tr>`;}
function render(){renderControls();renderMetrics();renderMap();renderInspector();renderWorkflow();renderScenarios();}
function selectObject(value){const parts=value.split(':'),type=parts[0],id=parts[1],rows=type==='catchment'?C.catchments:type==='pipe'?C.pipes:type==='node'?C.nodes:[];if(!rows.some(x=>x.id===id))return;selection={type,id};renderMap();renderInspector();}
function updateZoom(){const w=800/zoom,h=630/zoom;$('model-map').setAttribute('viewBox',`${(800-w)/2} ${(630-h)/2} ${w} ${h}`);$('zoom-in').disabled=zoom>=2.2;$('zoom-out').disabled=zoom<=1;}
function openSave(){if(saved.length>=20){notify('You have 20 saved scenarios. Export or remove one before saving another.');return;}$('scenario-name').value='';$('save-error').hidden=true;$('save-dialog').showModal();$('scenario-name').focus();}
function saveCurrent(name){name=String(name).trim().slice(0,60);if(!name)throw new Error('Give this scenario a name.');if(saved.length>=20)throw new Error('The demo supports up to 20 saved scenarios.');const row={id:'sc_'+(window.crypto&&window.crypto.randomUUID?window.crypto.randomUUID():Date.now().toString(36)+'_'+Math.random().toString(36).slice(2)),name,created:new Date().toISOString(),settings:C.validate(settings)};saved.push(row);if(!storeScenarios()){saved.pop();throw new Error('Browser storage is unavailable. Export the current plan to keep your choices.');}renderScenarios();return row;}
function download(data,filename){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);notify('JSON download prepared.');}
function exportPlan(s=settings,name='Current refinement'){download(C.plan(s,name),'smrf-refinement-plan.json');}
function importPlan(data){if(!data||data.schema!=='smrf-explorer-plan/v1'||data.dataset!=='Fictional demo district — not Bellinge')throw new Error('Import an SMRF explorer plan exported from this demo.');const next=C.validate(data.settings);settings=next;settingsChanged();comparison='current';showView('explorer');notify('Imported refinement choices. Results were recalculated from demo data.');}
$('object-select').innerHTML='<optgroup label="Subcatchments">'+C.catchments.map(c=>`<option value="catchment:${c.id}">${c.id} · ${c.name}</option>`).join('')+'</optgroup><optgroup label="Pipes">'+C.pipes.map(p=>`<option value="pipe:${p.id}">${p.id} · ${p.from} → ${p.to}</option>`).join('')+'</optgroup><optgroup label="Nodes">'+C.nodes.map(p=>`<option value="node:${p.id}">${p.id} · ${p.type==='outfall'?'Outfall':'Junction'}</option>`).join('')+'</optgroup>';
$('data-rows').innerHTML=C.catchments.map(c=>`<tr><td><strong>${c.id}</strong></td><td>${n(c.area,2)}</td><td>${n(c.roof,2)}</td><td>${n(c.road,2)}</td><td>${n(c.parking,2)}</td><td>${n(c.green,2)}</td><td>${n(c.raster)}</td></tr>`).join('');
all('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));all('[data-go]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.go)));window.addEventListener('hashchange',()=>showView(location.hash.slice(1),false));
$('source').addEventListener('change',e=>{settings.source=e.target.value;settingsChanged();});for(const k of ['streets','parking','green','terrain','alignment'])$(k).addEventListener('change',e=>{settings[k]=e.target.checked;settingsChanged();});$('width').addEventListener('input',e=>{settings.width=Number(e.target.value);settingsChanged();});
$('reset-button').addEventListener('click',()=>{settings=C.defaults();settingsChanged();notify('Draft reset. Saved scenarios are preserved.');});$('workflow-button').addEventListener('click',()=>showView('workflow'));
$('object-select').addEventListener('change',e=>selectObject(e.target.value));$('model-map').addEventListener('click',e=>{const obj=e.target.closest('[data-object]');if(obj)selectObject(obj.dataset.object);});$('model-map').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){const obj=e.target.closest('[data-object]');if(obj){e.preventDefault();selectObject(obj.dataset.object);const next=all('[data-object]').find(x=>x.dataset.object===obj.dataset.object);if(next)next.focus();}}});
all('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;renderMap();}));$('show-buildings').addEventListener('change',renderMap);$('show-labels').addEventListener('change',renderMap);
$('zoom-in').addEventListener('click',()=>{zoom=Math.min(2.2,zoom+.25);updateZoom();});$('zoom-out').addEventListener('click',()=>{zoom=Math.max(1,zoom-.25);updateZoom();});$('zoom-fit').addEventListener('click',()=>{zoom=1;updateZoom();});
$('inspector').addEventListener('change',e=>{if(e.target.id!=='manual-pct'||settings.source!=='manual')return;const v=Number(e.target.value);if(!e.target.value.trim()||!Number.isFinite(v)||v<0||v>100){$('manual-error').textContent='Enter a fraction from 0 to 100%.';$('manual-error').hidden=false;return;}settings.manual[selection.id]=v;settingsChanged();});
$('validate-button').addEventListener('click',()=>{const rows=C.diagnostics(settings);validated=signature();$('validation-receipt').innerHTML='<div class="panel-title"><h2>Demo validation</h2><span class="badge live">'+rows.filter(r=>r.pass).length+'/4 PASSED</span></div><div class="panel-body">'+rows.map(r=>`<div class="check-row"><span class="check-symbol">${r.pass?'✓':'!'}</span><div><strong>${r.name}</strong><p>${r.pass?r.detail:'Demo check failed.'}</p></div></div>`).join('')+'<p class="mini-note">These checks cover the demo attributes and fixed graph only. SWMM and geometry regeneration were not executed.</p></div>';notify('Demo checks complete. No hydraulic engine was run.');});
$('save-button').addEventListener('click',openSave);$('close-save').addEventListener('click',()=>$('save-dialog').close());$('cancel-save').addEventListener('click',()=>$('save-dialog').close());$('save-form').addEventListener('submit',e=>{e.preventDefault();try{saveCurrent($('scenario-name').value);$('save-dialog').close();showView('scenarios');notify('Scenario saved in this browser.');}catch(err){$('save-error').textContent=err.message;$('save-error').hidden=false;}});
$('compare-select').addEventListener('change',e=>{comparison=e.target.value;renderComparison();});$('scenario-cards').addEventListener('click',e=>{const b=e.target.closest('[data-scenario-action]');if(!b)return;const action=b.dataset.scenarioAction,id=b.dataset.id,s=saved.find(x=>x.id===id);if(action==='save')return openSave();if(action==='export-current')return exportPlan();if(action==='baseline'){settings=C.defaults();settingsChanged();showView('explorer');return;}if(!s)return;if(action==='load'){settings=C.validate(s.settings);settingsChanged();showView('explorer');notify('Loaded '+s.name+'.');}else if(action==='compare'){comparison=id;$('compare-select').value=id;renderComparison();}else if(action==='export')exportPlan(s.settings,s.name);else if(action==='delete'){const before=saved;saved=saved.filter(x=>x.id!==id);if(!storeScenarios()){saved=before;notify('Could not update browser storage. Your saved scenario was retained.');return;}renderScenarios();notify('Saved scenario removed.');}});
$('export-button').addEventListener('click',()=>exportPlan());$('demo-download').addEventListener('click',()=>download({schema:'smrf-demo-attributes/v1',dataset:'Fictional demo district — not Bellinge',geographic:false,catchments:C.catchments,nodes:C.nodes,pipes:C.pipes,notes:C.plan(C.defaults()).assumptions},'smrf-demo-attributes.json'));
$('import-button').addEventListener('click',()=>$('import-file').click());$('import-file').addEventListener('change',async e=>{const f=e.target.files&&e.target.files[0];if(!f)return;try{if(f.size>1024*1024)throw new Error('Use an exported plan smaller than 1 MB.');importPlan(JSON.parse(await f.text()));}catch(err){notify('Plan not imported: '+err.message);}finally{e.target.value='';}});
window.SMRFWorkspace={showView,notify};createBuildings();render();showView(location.hash.slice(1)||'project',false);
})();
